        const canvas = document.getElementById('solarCanvas');
        const ctx = canvas.getContext('2d');
        const planetsData = {json.dumps(planets)};

        function resize() {{
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }}
        window.onresize = resize;
        resize();

        let time = 0;
        const speed = 0.5; // Simulation speed factor

        function animate() {{
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            // Draw Sun
            ctx.beginPath();
            ctx.arc(centerX, centerY, 20, 0, Math.PI * 2);
            ctx.fillStyle = "#FFD700";
            ctx.shadowBlur = 30;
            ctx.shadowColor = "#FFD700";
            ctx.fill();
            ctx.shadowBlur = 0;

            planetsData.forEach((p, index) => {{
                // Scaling logic: 
                // We use a square root scale for distance so outer planets aren't off-screen
                const visualDist = Math.sqrt(p.distance) * 150;
                const angle = (time / p.period) * speed * Math.PI * 2;

                const x = centerX + Math.cos(angle) * visualDist;
                const y = centerY + Math.sin(angle) * visualDist;

                // Draw Orbit
                ctx.beginPath();
                ctx.arc(centerX, centerY, visualDist, 0, Math.PI * 2);
                ctx.strokeStyle = "rgba(255, 255, 255, 0.1)";
                ctx.stroke();

                // Draw Planet
                ctx.beginPath();
                ctx.arc(x, y, Math.max(2, p.radius * 2), 0, Math.PI * 2);
                ctx.fillStyle = p.color;
                ctx.fill();

                ctx.fillStyle = "white";
                ctx.fillText(p.name, x + 10, y + 5);
            }});

            time += 1;
            requestAnimationFrame(animate);
        }}

        animate();
    </script>
