            ctx.beginPath();
            ctx.arc(centerX, centerY, 18, 0, Math.PI * 2);
            ctx.shadowBlur = 35;
            ctx.shadowColor = "#FFD700";
            ctx.fillStyle = "#FFD700";
            ctx.fill();
            ctx.shadowBlur = 0;

