                grad.addColorStop(1, "black");

                ctx.beginPath();
                ctx.arc(x, y, Math.max(3, p.radius * 1.3), 0, Math.PI * 2);
                ctx.fillStyle = grad;
                ctx.fill();

                ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
                ctx.font = "10px Arial";
                ctx.fillText(p.name, x + 12, y + 4);
            }});

            requestAnimationFrame(animate);
        }

        requestAnimationFrame(animate);
    </script>
</body>
</html>
