using UnityEngine.UI;

public class TrajectoryPredictor : MonoBehaviour
{
    [Header("Physics Settings")]
    public Rigidbody2D rb;
    public float forceMultiplier = 5f;
    public int dotCount = 10;
    public float dotSpacing = 0.1f;

    [Header("UI Settings")]
    public GameObject dotPrefab; // A UI Image or Sprite prefab
    public Transform dotParent;  // Parent object to keep hierarchy clean

    private List<GameObject> dots = new List<GameObject>();
    private Vector2 startPoint;
    private Vector2 endPoint;
    private Vector2 direction;
    private float force;

    void Start()
    {
        // Initialize the dots and hide them
        for (int i = 0; i < dotCount; i++)
        {
            GameObject dot = Instantiate(dotPrefab, dotParent);
            dot.SetActive(false);
            dots.Add(dot);
        }
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            startPoint = Camera.main.ScreenToWorldPoint(Input.mousePosition);
            ShowDots();
        }

        if (Input.GetMouseButton(0))
        {
            endPoint = Camera.main.ScreenToWorldPoint(Input.mousePosition);

            // Calculate direction and force (inverted for "slingshot" feel)
            direction = startPoint - endPoint;
            force = direction.magnitude * forceMultiplier;

            UpdateTrajectory();
        }

        if (Input.GetMouseButtonUp(0))
        {
            Launch();
            HideDots();
        }
    }

    void UpdateTrajectory()
    {
        Vector2 velocity = direction * forceMultiplier;

        for (int i = 0; i < dotCount; i++)
        {
            float t = i * dotSpacing;
            // Standard kinematic equation: pos = start + (velocity * t) + (0.5 * gravity * t^2)
            Vector2 pos = (Vector2)transform.position + (velocity * t) + 0.5f * Physics2D.gravity * (t * t);

            dots[i].transform.position = pos;
        }
    }

    void Launch()
    {
        rb.velocity = direction * forceMultiplier;
    }

    void ShowDots()
    {
        foreach (var dot in dots) dot.SetActive(true);
    }

    void HideDots()
    {
        foreach (var dot in dots) dot.SetActive(false);
    }
}
