function drawHexBin(canvasId, pData, color) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const center = 75;
    const radius = 60;

    // Normalize stats for the radar chart
    const values = [
        pData.score / 10, 
        pData.hp / 100, 
        pData.hits / 20, 
        pData.items / 5, 
        pData.oppHits / 10,
        0.5 // Balance factor
    ];

    ctx.clearRect(0, 0, 150, 150);

    // Draw Grid
    ctx.strokeStyle = '#333';
    ctx.beginPath();
    for(let i=0; i<6; i++) {
        let x = center + radius * Math.cos(i * Math.PI / 3);
        let y = center + radius * Math.sin(i * Math.PI / 3);
        ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.stroke();

    // Draw Data
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.5;
    ctx.beginPath();
    for(let i=0; i<6; i++) {
        let r = radius * Math.min(values[i], 1);
        let x = center + r * Math.cos(i * Math.PI / 3);
        let y = center + r * Math.sin(i * Math.PI / 3);
        ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = color;
    ctx.globalAlpha = 1;
    ctx.stroke();
}

function triggerGameOver() {
