                                  std::to_string(s.losses) + " | " + std::to_string(s.gamesPlayed);
                sf::Text text(row, font, 18);
                text.setPosition(20, yOffset);
                ratingWin.draw(text);
                yOffset += 30;
            }
            ratingWin.display();
        }
    }
};

// ==========================================
// CONTROLLER: Input & Coordination
// ==========================================
class ChessController {
private:
    RatingManager& model;
    ChessView& view;
    sf::RenderWindow& mainWindow;

public:
    ChessController(RatingManager& m, ChessView& v, sf::RenderWindow& w) 
        : model(m), view(v), mainWindow(w) {}

    void handleInput() {
        sf::Event event;
        while (mainWindow.pollEvent(event)) {
            if (event.type == sf::Event::Closed) mainWindow.close();

            if (event.type == sf::Event::MouseButtonPressed) {
                sf::Vector2i pos = sf::Mouse::getPosition(mainWindow);

                // Logic for "Player Rating" Button (Assume coordinates)
                if (pos.y > 620 && pos.x > 330 && pos.x < 480) {
                    view.showRatingWindow(model);
                }

                // Logic for "Start Game" (Simulating a win for demo)
                if (pos.y > 620 && pos.x < 160) {
                    model.recordMatch("Alice", "Bob");
                    std::cout << "Match Recorded: Alice won against Bob\n";
                }
            }
        }
    }

    void updateView() {
        mainWindow.clear(sf::Color(50, 50, 50));
        view.drawBoard(mainWindow);

        // Draw UI Buttons (Simplified)
        sf::RectangleShape btn(sf::Vector2f(150, 40));
        btn.setPosition(330, 620);
        btn.setFillColor(sf::Color::Blue);
        mainWindow.draw(btn);

        mainWindow.display();
    }
};

int main() {
    sf::RenderWindow window(sf::VideoMode(800, 700), "Chess MVC");
    RatingManager model;
    ChessView view;
    ChessController controller(model, view, window);

    while (window.isOpen()) {
        controller.handleInput();
        controller.updateView();
    }
    return 0;
}
