    allowed_fields = ['firstName', 'lastName', 'weight', 'height', 'bodyType', 'profilePic']
    filtered_updates = {k: v for k, v in update_data.items() if k in allowed_fields}

    if not filtered_updates:
        return {"status": "error", "message": "No valid fields provided for update."}

    try:
        # Perform the update
        user_ref.update(filtered_updates)
        return {
            "status": "success", 
            "message": f"Successfully updated {list(filtered_updates.keys())}"
        }
    except Exception as e:
        print(f"Error updating profile for {uid}: {e}")
        return {"status": "error", "message": str(e)}
