This Python function (intended for a Firebase Cloud Function) ensures that the physical stats are stored as numbers and that the profile is marked as complete.

```python
import firebase_admin
from firebase_admin import firestore

def process_signup_data(uid, data):
    """
    Validates and saves user profile data to Firestore.

    :param uid: The unique ID from Firebase Authentication.
    :param data: Dictionary containing firstName, lastName, weight, height, bodyType, and profilePic.
    """
    db = firestore.client()

    try:
        # 1. Data Validation & Type Casting
        # Ensure weight and height are stored as floats for future health calculations
        weight = float(data.get('weight', 0))
        height = float(data.get('height', 0))
        first_name = str(data.get('firstName', '')).strip()
        last_name = str(data.get('lastName', '')).strip()

        if not first_name or not last_name:
            return {"status": "error", "message": "Names cannot be empty"}

        # 2. Prepare the Firestore document
        user_profile = {
            "firstName": first_name,
            "lastName": last_name,
            "weight": weight,
            "height": height,
            "bodyType": data.get('bodyType'),
            "profilePic": data.get('profilePic'),
            "profileCompleted": True,
            "updatedAt": firestore.SERVER_TIMESTAMP
        }

        # 3. Update the document
        db.collection('users').document(uid).set(user_profile, merge=True)

        return {"status": "success", "message": "User profile created successfully"}

    except ValueError:
        return {"status": "error", "message": "Weight and Height must be numeric values"}
    except Exception as e:
        return {"status": "error", "message": str(e)}
