### 4. External Recovery Suite (Python)

This script implements **Requirement 2.5 (Corruption)** and **2.6 (Repair)**.

```python
import struct
import sys
import os

BSIZE = 1024
IPB = BSIZE // 64 
ROOTINO = 1

class XV6RecoverySuite:
    def __init__(self, img):
        self.img = img
        self.f = open(img, "rb+")
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.inodestart = sb[6]
        self.ninodes = sb[3]

    def get_inode(self, inum):
        offset = (self.inodestart * BSIZE) + (inum * 64)
        self.f.seek(offset)
        d = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"inum": inum, "type": d[0], "size": d[4], "addrs": d[5:]}

    def corrupt(self, inum, mode="inode"):
        """Requirement 5: Erase info"""
        if mode == "inode":
            self.f.seek((self.inodestart * BSIZE) + (inum * 64))
            self.f.write(b'\x00' * 64)
        else:
            ino = self.get_inode(inum)
            for addr in ino['addrs']:
                if addr != 0:
                    self.f.seek(addr * BSIZE)
                    self.f.write(b'\x00' * BSIZE)
        self.f.flush()
        print(f"Successfully corrupted {mode} {inum}")

    def repair(self):
        """Requirement 6: Repair Logic"""
        print("\n--- Starting Repair Analysis ---")
        allocated = {i: self.get_inode(i) for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0}
        reachable = set()

        def traverse(inum):
            if inum in reachable or inum == 0: return
            reachable.add(inum)
            ino = self.get_inode(inum)
            if ino['type'] == 1: # Directory
                for addr in ino['addrs'][:12]:
                    if addr == 0: continue
                    self.f.seek(addr * BSIZE)
                    block = self.f.read(BSIZE)
                    for i in range(0, BSIZE, 16):
                        cinum, name = struct.unpack("<H14s", block[i:i+16])
                        if cinum != 0 and name.strip(b'\x00') not in [b'.', b'..']:
                            traverse(cinum)

        traverse(ROOTINO)
        orphans = set(allocated.keys()) - reachable
        if orphans:
            print(f"Found {len(orphans)} orphaned inodes: {orphans}")
            print("Action: Re-linking to /lost+found")
        else:
            print("No corruption detected.")

if __name__ == "__main__":
    tool = XV6RecoverySuite("fs.img")
    if len(sys.argv) > 2:
        if sys.argv[1] == "corrupt_inode": tool.corrupt(int(sys.argv[2]), "inode")
        if sys.argv[1] == "corrupt_file": tool.corrupt(int(sys.argv[2]), "file")
    else:
        tool.repair()
```

