### 2. Kernel Modifications (xv6-riscv Source)

#### A. `kernel/fs.h` (Metadata Structure)
```c
struct inode_info {
  uint type;
  short major;
  short minor;
  short nlink;
  uint size;
  uint addrs[13];
};
```

#### B. `kernel/sysfile.c` (System Call Implementation)
```c
#include "fs.h"
#include "buf.h"

uint64
sys_get_dinode(void)
{
  int inum;
  uint64 addr; 
  struct buf *bp;
  struct dinode *dip;
  struct superblock sb;

  if(argint(0, &inum) < 0 || argaddr(1, &addr) < 0)
    return -1;

  // Read superblock to find inode layout
  bp = bread(1, 1);
  memmove(&sb, bp->data, sizeof(sb));
  brelse(bp);

  if(inum < 0 || inum >= sb.ninodes) return -1;

  // Read the specific block containing the inode
  bp = bread(1, IBLOCK(inum, sb));
  dip = (struct dinode*)bp->data + (inum % IPB);

  struct inode_info info;
  info.type = dip->type;
  info.nlink = dip->nlink;
  info.size = dip->size;
  memmove(info.addrs, dip->addrs, sizeof(info.addrs));
  brelse(bp);

  return copyout(myproc()->pagetable, addr, (char *)&info, sizeof(info));
}
```

