import firebase_admin
from firebase_admin import firestore

def get_user_profile_data(uid):
    """
    Retrieves user profile information from Firestore.

    :param uid: The unique Firebase Authentication UID of the user.
    :return: Dictionary of user data or None if not found.
    """
    try:
        db = firestore.client()
        user_ref = db.collection('users').document(uid)
        doc = user_ref.get()

        if doc.exists:
            return doc.to_dict()
        else:
