from firebase_admin import firestore, auth

def save_user_physical_stats(data):
    """
    Validates and saves user physical data to Firestore.

    :param data: Dictionary containing 'uid', 'weight', 'height', 'body_type'
    """
    db = firestore.client()

    uid = data.get('uid')
    weight = data.get('weight')
    height = data.get('height')
    body_type = data.get('body_type')

    # 1. Server-side Validation
    if not uid:
        return {"status": "error", "message": "User UID is required"}

    try:
        # Ensure weight and height are numeric
        weight_val = float(weight)
        height_val = float(height)

        if weight_val <= 0 or height_val <= 0:
            raise ValueError("Stats must be positive numbers")

    except (ValueError, TypeError):
        return {"status": "error", "message": "Invalid weight or height format"}

    # 2. Save to Firestore
    try:
        user_ref = db.collection('users').document(uid)
        user_ref.update({
            'weight': weight_val,
            'height': height_val,
            'bodyType': body_type,
            'profileCompleted': True,
            'updatedAt': firestore.SERVER_TIMESTAMP
        })
        return {"status": "success", "message": "Profile updated successfully"}
    except Exception as e:
        return {"status": "error", "message": str(e)}
