import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';

class SignupService {
  final FirebaseAuth _auth = FirebaseAuth.instance;
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  Future<void> finalizeSignup({
    required String email,
    required String password,
    required String firstName,
    required String lastName,
    required String weight,
    required String height,
    required String bodyType,
    required String profilePicUrl,
  }) async {
    try {
      // 1. Create User in Firebase Auth
      UserCredential userCredential = await _auth.createUserWithEmailAndPassword(
        email: email,
        password: password,
      );

      String uid = userCredential.user!.uid;

      // 2. Save detailed profile to Firestore
      // We parse weight and height to double for better data querying later
      await _db.collection('users').document(uid).set({
        'uid': uid,
        'email': email,
        'firstName': firstName,
        'lastName': lastName,
        'weight': double.tryParse(weight) ?? 0.0,
        'height': double.tryParse(height) ?? 0.0,
        'bodyType': bodyType,
        'profilePic': profilePicUrl,
        'createdAt': FieldValue.serverTimestamp(),
      });

      print("User registered and profile saved!");
    } on FirebaseAuthException catch (e) {
      print("Auth Error: ${e.message}");
      rethrow;
    } catch (e) {
      print("General Error: $e");
      rethrow;
    }
  }
}
```

