import firebase_admin
from firebase_admin import firestore

def update_user_profile_data(uid, update_data):
    """
    Updates specific fields in the user's Firestore profile.

    :param uid: The unique ID of the user.
    :param update_data: A dictionary containing fields to update (e.g., weight, height).
    :return: Dictionary with status and message.
    """
    db = firestore.client()
    user_ref = db.collection('users').document(uid)

    # List of allowed fields to prevent malicious data injection
    allowed_fields = ['firstName', 'lastName', 'weight', 'height', 'bodyType', 'profilePic']
    filtered_updates = {k: v for k, v in update_data.items() if k in allowed_fields}

    if not filtered_updates:
        return {"status": "error", "message": "No valid fields provided for update."}

    try:
        # Perform the update
        user_ref.update(filtered_updates)
        return {
            "status": "success", 
            "message": f"Successfully updated {list(filtered_updates.keys())}"
        }
    except Exception as e:
        print(f"Error updating profile for {uid}: {e}")
        return {"status": "error", "message": str(e)}
