          {currentPath ? <Path d={currentPath} stroke="blue" strokeWidth="2" fill="none" /> : null}

          {/* Render points only if not finished. 
              When batchIndex changes, this list updates, erasing previous points. */}
          {!isFinished && currentBatch.map((pt, index) => {
            const sx = scale(pt.x);
            const sy = scale(pt.y);
            const isActive = index === nextPointToHit;
            const isDone = index < nextPointToHit;

            return (
              <G key={`pt-${batchIndex}-${index}`}>
