This program recursively traverses the directory tree and prints names and inodes.
```c
#include "kernel/types.h"
#include "kernel/stat.h"
#include "user/user.h"
#include "kernel/fs.h"

void walk(char *path) {
  int fd;
  struct dirent de;
  struct stat st;
  char buf[512], *p;

  if((fd = open(path, 0)) < 0) return;
  if(fstat(fd, &st) < 0 || st.type != T_DIR) { close(fd); return; }

  while(read(fd, &de, sizeof(de)) == sizeof(de)) {
    if(de.inum == 0 || strcmp(de.name, ".") == 0 || strcmp(de.name, "..") == 0)
      continue;
    printf("Path: %s/%s | Inode: %d\n", path, de.name, de.inum);

    strcpy(buf, path);
    p = buf+strlen(buf);
    *p++ = '/';
    memmove(p, de.name, DIRSIZ);
    p[DIRSIZ] = 0;
    walk(buf);
  }
  close(fd);
}

int main() {
  walk("");
  exit(0);
}
